style.css:
@-moz-document domain("rewards.bing.com") {
/* Regla principal: fondo oscuro, texto claro */
html, body, div, main, section, article, header, footer, nav, aside {
background-color: #1e1e1e !important;
color: #e0e0e0 !important;
border-color: #444 !important;
}
/* Cambiar color de los enlaces */
a {
  color: #86b9fc !important;
}
a:visited {
  color: #9e6dd4 !important;
}

/* Cabeceras */
h1 h2, h3, h4, h5, h6 {
   color: #ffffff !important;
}

/* Evitar que las imágenes y videos se inviertan */
img, video, svg {
  filter: invert(0) !important;
  }


*:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(2) > *:nth-child(2) *:nth-child(2),
*:nth-child(2) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(2) > *:nth-child(2) *:nth-child(2),
*:nth-child(3) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) > *:nth-child(1) *:nth-child(2) > *:nth-child(2) *:nth-child(2),
*:nth-child(4) > *:nth-child(1) > *:nth-child(1) *:nth-child(1) > *:nth-child(2) > *:nth-child(2) > *:nth-child(1) > *:nth-child(2) {
   color: white !important;
}

div#rewardsBanner.theme-dark {
  background: #1e1e1e !important;
}
#rewards-suggestedSearch-searchbox {
	background: #0D0D0D !important;
}
.icon > svg {
	background: #0D0D0D !important;
}
.rewards_searchboxForm > .icon {
  background: #0D0D0D !important;
  }
}
